Actionscript.script:
onClipEvent(load){
    子弹属性 = _root.子弹属性初始化(this);

    // 定义所有手雷类型（可根据需要增减）
    var 手雷类型列表 = ["高爆手雷", "地瓜手雷", "普通手雷"];

    // 随机选择一种手雷类型（核心修改点）
    子弹属性.子弹种类 = 手雷类型列表[Math.floor(Math.random() * 手雷类型列表.length)];

    // 其他属性保持不变
    子弹属性.声音 = "";
    子弹属性.霰弹值 = 1;
    子弹属性.发射效果 = "";
    子弹属性.子弹散射度 = 4; // 修复了原代码中的语法错误（缺少值）
// 等级判断
	if (_parent._parent.等级 >= 50) {
		子弹属性.子弹威力 = _parent._parent.空手攻击力 * 3.5;
	} else {
		子弹属性.子弹威力 = _parent._parent.空手攻击力 * 2.5;
	}
    子弹属性.子弹速度 = 20;
    子弹属性.Z轴攻击范围 = 25; // 修复了原代码中的语法错误（句号改为分号）
    子弹属性.击倒率 = 5;
    子弹属性.水平击退速度 = NaN;
    子弹属性.垂直击退速度 = NaN;

    // 保持原有逻辑不变
    _root.子弹区域shoot传递(子弹属性);
}

onClipEvent(load){
	子弹属性 = _root.子弹属性初始化(this);
	// 根据等级选择不同的攻击代码
	if (_parent._parent.等级 >= 50) {
		// ========== 等级范围内 ==========
		子弹属性.声音 = "火流.wav";
		子弹属性.霰弹值 = 1;
		子弹属性.子弹散射度 = 0;
		子弹属性.子弹种类 = "近战子弹";
		子弹属性.子弹威力 = _parent._parent.空手攻击力;
		子弹属性.子弹速度 = 0;
		子弹属性.Z轴攻击范围 = 30;
		子弹属性.击倒率 = 10;
		子弹属性.水平击退速度 = 10;
		子弹属性.垂直击退速度 = 3;
		子弹属性.伤害类型 = "魔法";
		子弹属性.魔法伤害属性 = "热";


	} else {
		// ========== 等级范围外 ==========
		子弹属性.声音 = "火流.wav";  
		子弹属性.霰弹值 = 1;
		子弹属性.子弹散射度 = 0;
		子弹属性.子弹种类 = "近战子弹";
		子弹属性.子弹威力 = _parent._parent.空手攻击力;
		子弹属性.子弹速度 = 0;
		子弹属性.Z轴攻击范围 = 30;
		子弹属性.击倒率 = 10;
		子弹属性.水平击退速度 = 10;
		子弹属性.垂直击退速度 = 3;

	}

	// 公共属性（两边都需要）
	子弹属性.发射效果 = "高爆枪火";
	子弹属性.区域定位area = this.area;

	_root.子弹区域shoot传递(子弹属性);
}

onClipEvent(load){
	子弹属性 = _root.子弹属性初始化(this);

	// 根据等级选择不同的攻击代码
	if (_parent._parent.等级 >= 50) {
		// ========== 等级35以上：魔法攻击代码 ==========
		子弹属性.声音 = "火流.wav";
		子弹属性.霰弹值 = 1;
		子弹属性.子弹散射度 = 0;
		子弹属性.子弹种类 = "近战子弹";
		子弹属性.子弹威力 = _parent._parent.空手攻击力 * 1.1;
		子弹属性.子弹速度 = 0;
		子弹属性.Z轴攻击范围 = 30;
		子弹属性.击倒率 = 10;
		子弹属性.水平击退速度 = 10;
		子弹属性.垂直击退速度 = 3;
		子弹属性.伤害类型 = "魔法";
		子弹属性.魔法伤害属性 = "热";

		// 35级以上可添加额外特效
		// 子弹属性.发射效果 = "火焰特效";
		// 子弹属性.击中效果 = "爆炸特效";

	} else {
		// ========== 等级35以下：普通攻击代码 ==========
		子弹属性.声音 = "火流.wav";  // 可以改成其他声音，比如"普通攻击.wav"
		子弹属性.霰弹值 = 1;
		子弹属性.子弹散射度 = 0;
		子弹属性.子弹种类 = "近战子弹";
		子弹属性.子弹威力 = _parent._parent.空手攻击力* 1.5;
		子弹属性.子弹速度 = 0;
		子弹属性.Z轴攻击范围 = 30;
		子弹属性.击倒率 = 10;
		子弹属性.水平击退速度 = 10;
		子弹属性.垂直击退速度 = 3;
		子弹属性.伤害类型 = "物理";  // 普通物理伤害
		// 35级以下没有魔法伤害属性

		// 35级以下可添加其他特效
		// 子弹属性.发射效果 = "普通特效";
	}

	// 公共属性（两边都需要）
	子弹属性.发射效果 = "高爆枪火";
	子弹属性.区域定位area = this.area;

	// 非常用设置（根据需要取消注释）
	/*
	子弹属性.水平击退速度 = NaN;
	子弹属性.垂直击退速度 = NaN;
	子弹属性.发射效果 = "";
	子弹属性.击中地图效果 = "火花";
	子弹属性.击中后子弹的效果 = "";
	子弹属性.命中率 = NaN;
	子弹属性.固伤 = NaN;
	子弹属性.百分比伤害 = NaN;
	子弹属性.血量上限击溃 = NaN;
	子弹属性.防御粉碎 = NaN;
	*/

	_root.子弹区域shoot传递(子弹属性);
}

